import random
random.seed(20240614)

# —— 基础契约 ——
d = DSU(5)
assert d.count == 5
assert d.connected(0, 0) is True
assert d.connected(0, 1) is False
d.union(0, 1)
d.union(2, 3)
assert d.connected(0, 1) is True
assert d.connected(2, 3) is True
assert d.connected(1, 2) is False
assert d.count == 3                      # {0,1} {2,3} {4}
d.union(1, 2)                            # 合并两组
assert d.connected(0, 3) is True
assert d.count == 2                      # {0,1,2,3} {4}
d.union(0, 3)                            # 已连通,count 不变
assert d.count == 2
assert d.connected(4, 0) is False

# —— 随机对拍:朴素 relabel 并查集作参照 ——
class _Naive:
    def __init__(self, n):
        self.lab = list(range(n))        # lab[x] = x 所在分量的标签
    def union(self, x, y):
        a, b = self.lab[x], self.lab[y]
        if a != b:
            for i in range(len(self.lab)):
                if self.lab[i] == b:
                    self.lab[i] = a      # 把 b 整组改名为 a
    def connected(self, x, y):
        return self.lab[x] == self.lab[y]
    def count(self):
        return len(set(self.lab))

for _ in range(200):
    n = random.randint(1, 30)
    dsu = DSU(n)
    ref = _Naive(n)
    for _ in range(random.randint(0, 40)):
        x, y = random.randrange(n), random.randrange(n)
        dsu.union(x, y)
        ref.union(x, y)
    for a in range(n):
        for b in range(n):
            assert dsu.connected(a, b) == ref.connected(a, b), (a, b)
    assert dsu.count == ref.count(), (dsu.count, ref.count())

