class DSU:
    """并查集:路径压缩 + 按秩(rank)合并。
    rank 是每棵树高度的上界;合并时矮树挂到高树下,树高几乎不增长。"""
    def __init__(self, n):
        self.parent = list(range(n))   # parent[x]==x 即 x 为根
        self.rank = [0] * n            # 每棵树高度的上界
        self.count = n                 # 当前连通分量数

    def find(self, x):
        # 迭代两趟:先找到根,再把路径上的结点直接挂到根(路径压缩)
        root = x
        while self.parent[root] != root:
            root = self.parent[root]
        while self.parent[x] != root:
            self.parent[x], x = root, self.parent[x]
        return root

    def union(self, x, y):
        rx, ry = self.find(x), self.find(y)
        if rx == ry:
            return False               # 已同集合,不合并
        if self.rank[rx] < self.rank[ry]:
            rx, ry = ry, rx            # 保证 rx 是更高(或等高)的那棵
        self.parent[ry] = rx           # 矮树挂到高树
        if self.rank[rx] == self.rank[ry]:
            self.rank[rx] += 1         # 等高合并,树高 +1
        self.count -= 1
        return True

    def connected(self, x, y):
        return self.find(x) == self.find(y)

class DSU:
    """并查集:路径压缩 + 按大小(size)合并。
    size 记录每棵树的结点数;合并时小树挂到大树下,并能 O(1) 取连通块大小。"""
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n            # 每棵树的结点数
        self.count = n

    def find(self, x):
        root = x
        while self.parent[root] != root:
            root = self.parent[root]
        while self.parent[x] != root:  # 路径压缩
            self.parent[x], x = root, self.parent[x]
        return root

    def union(self, x, y):
        rx, ry = self.find(x), self.find(y)
        if rx == ry:
            return False
        if self.size[rx] < self.size[ry]:
            rx, ry = ry, rx            # 保证 rx 是更大的那棵
        self.parent[ry] = rx           # 小树挂到大树
        self.size[rx] += self.size[ry] # 合并后累加结点数
        self.count -= 1
        return True

    def connected(self, x, y):
        return self.find(x) == self.find(y)

class DSU:
    """对照写法:只做路径压缩,不按秩 / 大小平衡。
    union 固定把 x 的根挂到 y 的根下,树可能长歪;
    但递归路径压缩仍把单次摊还压到 O(log n),小规模下足够快。"""
    def __init__(self, n):
        self.parent = list(range(n))
        self.count = n

    def find(self, x):
        # 递归 + 路径压缩:回溯时把 x 直接指向根
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        rx, ry = self.find(x), self.find(y)
        if rx == ry:
            return False
        self.parent[rx] = ry           # 固定方向合并,不做平衡
        self.count -= 1
        return True

    def connected(self, x, y):
        return self.find(x) == self.find(y)
